import{_ as d,o as r,c as a,a0 as o}from"./chunks/framework.Bmhw_dvp.js";const R=JSON.parse('{"title":"大模型推荐角色 v0.2（独立推导，未采用官方榜）","description":"","frontmatter":{},"headers":[],"relativePath":"llm_reco/reco-draft.md","filePath":"llm_reco/reco-draft.md"}'),e={name:"llm_reco/reco-draft.md"};function h(l,t,n,s,b,i){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="大模型推荐角色-v0-2-独立推导-未采用官方榜" tabindex="-1">大模型推荐角色 v0.2（独立推导，未采用官方榜） <a class="header-anchor" href="#大模型推荐角色-v0-2-独立推导-未采用官方榜" aria-label="Permalink to &quot;大模型推荐角色 v0.2（独立推导，未采用官方榜）&quot;">​</a></h1><blockquote><p>本版<strong>不参考</strong>官方讨伐战强度榜 / 新手指南点名，仅依据 <code>char_data.json</code> 角色数据与系统机制事实推导。 方法论见 <code>reco-method.md</code>；完整推理过程与候选原文核验见 <code>reasoning-log.md</code>。 说明：370 名角色中仅核验约 30 个候选，下列为&quot;<strong>经核验的突出样本</strong>&quot;，非穷举；其余 SSR 可按方法论自行判断。</p></blockquote><h2 id="推荐标准-一句话版" tabindex="-1">推荐标准（一句话版） <a class="header-anchor" href="#推荐标准-一句话版" aria-label="Permalink to &quot;推荐标准（一句话版）&quot;">​</a></h2><p><strong>机制稀缺度 × 公式独立乘区 × 站场能力 × 满突成本</strong>，不看出身、不看官方榜。</p><hr><h2 id="一、不撤退站场核心-最高权重-全游戏仅-8-人" tabindex="-1">一、不撤退站场核心（最高权重，全游戏仅 8 人） <a class="header-anchor" href="#一、不撤退站场核心-最高权重-全游戏仅-8-人" aria-label="Permalink to &quot;一、不撤退站场核心（最高权重，全游戏仅 8 人）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>角色</th><th>稀有</th><th>核验要点</th><th>为什么强</th></tr></thead><tbody><tr><td>ビートソニック・アキレス</td><td>SSR</td><td>不撤退 + 血量&lt;20% 回 25~50% 体力(1次)</td><td>站场输出，副坦向</td></tr><tr><td>ブライドハルカ・リバース</td><td>SSR</td><td>不撤退 + 攻击 521(上限) + 10% 即死(失败叠攻上限50%) + &lt;10% 降仇恨</td><td>攻防一体，最强不撤退包之一</td></tr><tr><td>真夏のハルカ</td><td>SSR</td><td>不撤退 + 必杀眩晕+50/防御+75/&lt;20%必杀+50</td><td>站场+控场</td></tr><tr><td>閃忍マユリ</td><td>R</td><td>不撤退 + 必杀 <strong>15× 无视防御</strong>(自承100%体力)</td><td>全游戏最暴力单体核弹，R 白送</td></tr><tr><td>FM77</td><td>R</td><td>不撤退（免费获取）</td><td>零成本拿到稀缺站场机制</td></tr><tr><td>神騎フローレル / 閃忍レイナ</td><td>R/SR</td><td>不撤退</td><td>低成本站场补位</td></tr><tr><td>神騎プロキオン</td><td>SR</td><td>不撤退</td><td>同上</td></tr></tbody></table><blockquote><p>新手优先把 <strong>FM77 / 閃忍マユリ</strong> 满突——用 R 卡成本拿到全游戏前 2% 的站场机制。</p></blockquote><hr><h2 id="二、顶级对策-稀缺机制-各仅-1-人-s-级必看" tabindex="-1">二、顶级对策 / 稀缺机制（各仅 1 人，S 级必看） <a class="header-anchor" href="#二、顶级对策-稀缺机制-各仅-1-人-s-级必看" aria-label="Permalink to &quot;二、顶级对策 / 稀缺机制（各仅 1 人，S 级必看）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>角色</th><th>稀有</th><th>核验要点</th><th>为什么强</th></tr></thead><tbody><tr><td>超昂閃忍ナリカ</td><td>SSR</td><td><strong>复活</strong>(火种) + 自然体力消耗停 25% + 双修 521/521/500</td><td>唯一复活位，泛用顶级</td></tr><tr><td>体育祭のヤブルー</td><td>SSR</td><td><strong>全异常免疫</strong>(独 1) + 出战全队必杀+25% + 必杀全体 50%魅惑/75%束缚</td><td>唯一真·全免控 + 巨型团队硬控</td></tr><tr><td>妹の1024</td><td>SSR</td><td>普攻 80% 概率友军必杀+10%(自身同步) + 必杀 场地速度+30% / 全队必杀+30%(叠5次)</td><td>最强充能核心之一（充能虽通胀，但她是&quot;叠加+自同步&quot;的顶配）</td></tr></tbody></table><hr><h2 id="三、稀有增益辅助-攻击增益仅-3-人-魔法增益仅-1-人" tabindex="-1">三、稀有增益辅助（攻击增益仅 3 人，魔法增益仅 1 人） <a class="header-anchor" href="#三、稀有增益辅助-攻击增益仅-3-人-魔法增益仅-1-人" aria-label="Permalink to &quot;三、稀有增益辅助（攻击增益仅 3 人，魔法增益仅 1 人）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>角色</th><th>稀有</th><th>核验要点</th><th>为什么强</th></tr></thead><tbody><tr><td>真夏のイーイー</td><td>SSR</td><td>在场友军出战攻击+30%(盛夏+50/速度+25) + 必杀横排 6×魔法 + 全队眩晕抵抗+50</td><td>攻击增益仅 3 人之一，兼控场</td></tr><tr><td>黒門天・屍寺炎斎</td><td>SSR</td><td>&lt;30%/65% 双节点 每秒5%回血+防御+100% + 必杀 10×魔法(存活攻击+30%上限150%)</td><td>攻击增益仅 3 人之一，自续航</td></tr><tr><td>魔女ミヤビ</td><td>SSR</td><td>出战敌方防速−20%(+魔女人数×10%增幅)；必杀全体 4×魔法</td><td>信号抽取标记&quot;攻击/魔法增益&quot;稀有持有者（具体增益幅度待全量核实），其&quot;敌方防速−20%&quot;已是罕见减益</td></tr></tbody></table><blockquote><p>增益在公式里<strong>相加</strong>，多个不同类增益来源比堆高单个更划算——这类辅助的价值被放大。</p></blockquote><hr><h2 id="四、免控领域-治疗-被动、无消耗-性价比最高的对策位" tabindex="-1">四、免控领域 + 治疗（被动、无消耗，性价比最高的对策位） <a class="header-anchor" href="#四、免控领域-治疗-被动、无消耗-性价比最高的对策位" aria-label="Permalink to &quot;四、免控领域 + 治疗（被动、无消耗，性价比最高的对策位）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>角色</th><th>稀有</th><th>核验要点</th><th>为什么强</th></tr></thead><tbody><tr><td>制服ニャンコ</td><td>SSR</td><td>在场全队 毒·魅惑·束缚(+/眩晕)免疫 + 必杀自身回50%/全队回30%/全队输出+20%</td><td>免控 + 治疗二合一</td></tr><tr><td>閃忍ニャンコ</td><td>SSR</td><td>在场全队 毒·魅惑·束缚·眩晕 免疫 + 必杀单体友军回100%+攻防速+30%</td><td>免控领域 + 爆发单奶</td></tr><tr><td>魔女フタバ</td><td>R</td><td>在场全队 毒·魅惑·眩晕·束缚 免疫 + 必杀横排 6×魔法</td><td>R 卡里的全队免控领域，新手对策核心</td></tr><tr><td>六の法杖セラフィール</td><td>SSR</td><td>出战<strong>清除全队异常/减益</strong>(+回15%) + 场地 5%/s 回血</td><td>极稀有的&quot;被动解控&quot;治疗</td></tr><tr><td>ビートプレジデント・シーラ</td><td>SSR</td><td>普攻 15% 概率附加必中魅惑/束缚/输出−20 + 必杀全队 2.5%/s 回血</td><td>治疗 + 软控场</td></tr><tr><td>アイドルの奉輪こもり</td><td>SSR</td><td><strong>撤退时</strong>全队回 50% + 攻防+30%（死亡即全队大补）</td><td>独特的&quot;退场收益&quot;机制</td></tr><tr><td>魔女シズク</td><td>R</td><td>出战全队 1~2%/s 回血 + 必杀全体 2~4×物理 + 场地 2~3%/s 回血</td><td>廉价群体治疗</td></tr></tbody></table><hr><h2 id="五、破防-减益-独立乘区-对高防-boss-暴涨" tabindex="-1">五、破防 / 减益（独立乘区，对高防 boss 暴涨） <a class="header-anchor" href="#五、破防-减益-独立乘区-对高防-boss-暴涨" aria-label="Permalink to &quot;五、破防 / 减益（独立乘区，对高防 boss 暴涨）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>角色</th><th>稀有</th><th>核验要点</th><th>为什么强</th></tr></thead><tbody><tr><td>鬼の斗羽大洋</td><td>SSR</td><td>出战 敌方输出−25%/我方+25% + 必杀 <strong>全体攻防−60%</strong></td><td>减益幅度罕见，顶级破防</td></tr><tr><td>神騎ハニーエル</td><td>R</td><td>自身魔法免疫 + 全队 眩晕·束缚 免疫 + 必杀穿透蜂蜜魔免</td><td>R 卡魔免对策专精</td></tr><tr><td>閃忍マユリ</td><td>R</td><td>见第一节：15× 无视防御</td><td>破防核弹</td></tr></tbody></table><hr><h2 id="六、硬控对策-r-卡廉价方案" tabindex="-1">六、硬控对策（R 卡廉价方案） <a class="header-anchor" href="#六、硬控对策-r-卡廉价方案" aria-label="Permalink to &quot;六、硬控对策（R 卡廉价方案）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>角色</th><th>稀有</th><th>核验要点</th><th>为什么强</th></tr></thead><tbody><tr><td>エスカ・アメイズ</td><td>R</td><td>必杀 全体 <strong>必中魅惑</strong>(魅惑免疫除外)</td><td>廉价硬魅惑，对魅惑 susceptible 敌人</td></tr><tr><td>閃忍クサリ</td><td>R</td><td>必杀 全体 <strong>强制眩晕</strong>(眩晕免疫除外) + 束缚 + 速度−20</td><td>廉价硬眩晕</td></tr><tr><td>閃忍ツルコ</td><td>R</td><td>出战自身速度+30 + 必杀全体 2~4×物理 + 眩晕+50</td><td>控场 + 速度</td></tr></tbody></table><hr><h2 id="七、新手核心-低成本满突-按机制而非官方点名" tabindex="-1">七、新手核心（低成本满突，按机制而非官方点名） <a class="header-anchor" href="#七、新手核心-低成本满突-按机制而非官方点名" aria-label="Permalink to &quot;七、新手核心（低成本满突，按机制而非官方点名）&quot;">​</a></h2><blockquote><p>铁律：满突★5 的 R ≫ 零突★1 的 SSR。下列是<strong>机制稀缺且易满突</strong>的 R/SR，构成新号起步底盘：</p></blockquote><table tabindex="0"><thead><tr><th>角色</th><th>稀有</th><th>承担机制</th><th>备注</th></tr></thead><tbody><tr><td>FM77</td><td>R</td><td>不撤退</td><td>免费获取</td></tr><tr><td>閃忍マユリ</td><td>R</td><td>不撤退 + 15× 无视防御核弹</td><td>站场 + 爆发</td></tr><tr><td>神騎アルゴル</td><td>R</td><td>出战场地速度+25% + 必杀全队必杀+30%</td><td>廉价充能/速度</td></tr><tr><td>神騎ハニーエル</td><td>R</td><td>魔法免疫 + 全队眩晕/束缚免疫 + 破魔免</td><td>对策专精</td></tr><tr><td>閃忍サイカ</td><td>R</td><td>出战<strong>敌方时停 2.5~4s</strong>(独一份开局冻结) + 低速3人速度+25%</td><td>机制独特</td></tr><tr><td>魔女シズク</td><td>R</td><td>廉价群体治疗</td><td>续航</td></tr><tr><td>エスカ・アメイズ</td><td>R</td><td>必中魅惑</td><td>硬控对策</td></tr><tr><td>閃忍クサリ</td><td>R</td><td>强制眩晕</td><td>硬控对策</td></tr><tr><td>魔女フタバ</td><td>R</td><td>全队 4 异常免疫领域</td><td>免控对策</td></tr><tr><td>ビートアミュレット・ノノノ</td><td>R</td><td>出战全队必杀+25% + 必杀全队攻防+30/敌方−30</td><td>攻防双向 buff</td></tr></tbody></table><blockquote><p>对比 v0.1：去掉了&quot;官方新手指南点名&quot;的 ビートアイドル・タマキ/アキエ、ハロウィンキレー、魔女ハッピー、暗之奉轮小守 等未核验卡，换成上述机制可核验的 R/SR。</p></blockquote><hr><h2 id="八、体系核心-阵营增益轴-按机制" tabindex="-1">八、体系核心（阵营增益轴，按机制） <a class="header-anchor" href="#八、体系核心-阵营增益轴-按机制" aria-label="Permalink to &quot;八、体系核心（阵营增益轴，按机制）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阵营</th><th>核验到的增益核心</th><th>说明</th></tr></thead><tbody><tr><td>魔女</td><td>魔女シズク(R) / 魔女ミヤビ</td><td>R 卡即体系核心的稀缺例；配&quot;超昂金&quot;按阵营加成收益最大</td></tr><tr><td>战士</td><td>エスカレイヤー 系</td><td>传说战士+：开幕对 3 名战士施加强力增益（待全量核验幅度）</td></tr><tr><td>闪忍</td><td>閃忍ハルカ / 閃忍サイカ(对彼岸花+300%)</td><td>闪忍阵营增益 + 速度轴</td></tr><tr><td>神骑</td><td>神騎エクシール / 神騎アルゴル(R)</td><td>神骑增益 + 廉价充能</td></tr></tbody></table><hr><p><em>本页为 AI 独立实验页面。修订记录：v0.1（2026-07-28，受官方榜影响）；v0.2（2026-07-29，脱离官方榜、基于角色数据与机制推导）。</em></p>',34)])])}const u=d(e,[["render",h]]);export{R as __pageData,u as default};
